// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        vm.prank(address(this), address(this));
        c = new PoCGame(address(this), 0);
    }

    function _test(address player, uint256 amount) internal {
        vm.assume(amount > 0);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(amount) {} catch { return; }
        uint256 expectedBet = amount;
        uint256 actualBet;
        try c.currentBetLimit() returns (uint256 __r) { actualBet = __r; } catch { return; }
        assertTrue(actualBet == expectedBet);
    }

    function testFuzz_test(address player, uint256 amount) public {
        _test(player, amount);
    }

    receive() external payable {}
}
